// NewCSR simple single-purpose register CSRs — readable transcriptions.
//
// Each golden module here is already plain structural RTL (async-reset
// always_ff + w_wen write arm + rdata packing). The readable rewrite is the
// golden body with the non-synthesizable `ifdef ENABLE_INITIAL_REG_ sim
// randomize-init block removed. FM-verified strict golden-vs-impl SUCCEEDED,
// no black box, no dont_verify. Generated by scripts/gen_newcsr_simplereg.py.


module MseccfgModule(
  input         clock,
  input         reset,
  input         w_wen,
  input  [63:0] w_wdata,
  output [63:0] rdata,
  output [1:0]  regOut_PMM
);

  reg [1:0] reg_PMM;
  always @(posedge clock or posedge reset) begin
    if (reset)
      reg_PMM <= 2'h0;
    else if (w_wen
             & (|{&(w_wdata[33:32]), w_wdata[33:32] == 2'h2, w_wdata[33:32] == 2'h0}))
      reg_PMM <= w_wdata[33:32];
  end
  assign rdata = {30'h0, reg_PMM, 32'h0};
  assign regOut_PMM = reg_PMM;
endmodule


