module VcsrModule(
  input         clock,
  input         w_wen,
  input  [63:0] w_wdata,
  output [63:0] rdata,
  input         robCommit_vxsat_valid,
  input         robCommit_vxsat_bits,
  input         wAliasVxsat_wen,
  input  [63:0] wAliasVxsat_wdata,
  input         wAliasVxrm_wen,
  input  [63:0] wAliasVxrm_wdata,
  output        vxsat,
  output [1:0]  vxrm
);

  reg       reg_VXSAT;
  reg [1:0] reg_VXRM;
  always @(posedge clock) begin
    if (robCommit_vxsat_valid)
      reg_VXSAT <= reg_VXSAT | robCommit_vxsat_bits;
    else if (w_wen | wAliasVxsat_wen)
      reg_VXSAT <= wAliasVxsat_wen & wAliasVxsat_wdata[0] | w_wen & w_wdata[0];
    if (w_wen | wAliasVxrm_wen)
      reg_VXRM <=
        (wAliasVxrm_wen ? wAliasVxrm_wdata[1:0] : 2'h0) | (w_wen ? w_wdata[2:1] : 2'h0);
  end
  assign rdata = {61'h0, reg_VXRM, reg_VXSAT};
  assign vxsat = reg_VXSAT;
  assign vxrm = reg_VXRM;
endmodule


